@page "/apply"
@rendermode InteractiveServer
@using sv_50c809c61fd7422dae2c67155e4b356b.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (_submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted Successfully!</h2>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        @* Step Content *@
        <div class="step-content">
            @switch (_currentStep)
            {
                case 0:
                    @RenderPersonalInfo()
                    break;
                case 1:
                    @RenderWorkHistory()
                    break;
                case 2:
                    @RenderReferences()
                    break;
                case 3:
                    @RenderCoverLetter()
                    break;
                case 4:
                    @RenderReview()
                    break;
            }
        </div>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="error-message">@_errorMessage</div>
        }
    }
</div>

@* Step 1: Personal Info *@
@{
    RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="_fullName" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="_email" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="_phone" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <textarea id="address" @bind="_address" placeholder="Enter your address"></textarea>
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                @if (_isValidating)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    };
}

@* Step 2: Work History *@
@{
    RenderFragment RenderWorkHistory() => __builder =>
    {
        <h2>Work History</h2>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var index = i;
            var entry = _workEntries[index];
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (_workEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" value="@entry.Company" @onchange="(e) => UpdateWorkEntry(index, entry with { Company = e.Value?.ToString() ?? string.Empty })" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" value="@entry.Title" @onchange="(e) => UpdateWorkEntry(index, entry with { Title = e.Value?.ToString() ?? string.Empty })" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" value="@entry.StartDate.ToString("yyyy-MM-dd")" @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" value="@entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" disabled="@entry.IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" checked="@entry.IsCurrent" @onchange="(e) => UpdateWorkEntry(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description *</label>
                    <textarea value="@entry.Description" @onchange="(e) => UpdateWorkEntry(index, entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
