    font-size: 1rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-next {
    background: #0d6efd;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-back {
    background: #6c757d;
    color: #fff;
}

.btn-back:hover {
    background: #5c636a;
}

.btn-submit {
    background: #198754;
    color: #fff;
    font-weight: bold;
}

.btn-submit:hover:not(:disabled) {
    background: #157347;
}

.btn-add {
    background: transparent;
    border: 1px dashed #0d6efd;
    color: #0d6efd;
    width: 100%;
    padding: 0.75rem;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #e7f1ff;
}

.btn-remove {
    background: #dc3545;
    color: #fff;
    font-size: 0.85rem;
    padding: 0.4rem 0.8rem;
}

.btn-remove:hover {
    background: #bb2d3b;
}

.btn-edit {
    background: transparent;
    color: #0d6efd;
    font-size: 0.9rem;
    padding: 0.3rem 0.6rem;
    border: 1px solid #0d6efd;
}

.btn-edit:hover {
    background: #0d6efd;
    color: #fff;
}

button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

