.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    margin: 0;
}

