    padding: 3rem 2rem;
    background: #d1e7dd;
    border: 1px solid #badbcc;
    border-radius: 8px;
}

.confirmation h2 {
    color: #0f5132;
    margin-bottom: 1rem;
}

.confirmation p {
    color: #0f5132;
    font-size: 1.1rem;
}

